/** The world of the spec: slice 1's — Priya owns "SMOKE Field Manuals", Marco curates it, Reid reads it, Ann is a guest on it. Idempotent. */
function world(): array
{
    $id = base_by_key('smoke-field-manuals');
    if ($id === null) {
        $id = make_base(PRIYA, 'SMOKE Field Manuals', ['key' => 'smoke-field-manuals']);
        $p = as_member(PRIYA);
        act($p, '/bases/members/add.php', ['base' => $id, 'member' => MARCO, 'level' => 'curate']);
        act($p, '/bases/members/add.php', ['base' => $id, 'member' => REID, 'level' => 'read']);
        act($p, '/bases/members/add-guest.php', ['base' => $id, 'guest' => ANN]);
    }
    return ['base' => $id];
}

/** Post files (name => path, or [name, path, mime]) to a handler as a person, JSON: [status, body]. */
function upload(string $jar, string $path, array $fields, array $files): array
{
    $tok = csrf_of(req('GET', '/', ['jar' => $jar])['body']);
    $post = $fields + ['csrf_token' => $tok];
    $i = 0;
    foreach ($files as $name => $file) {
        [$fname, $fpath, $mime] = is_array($file) ? $file + [2 => ''] : [$name, $file, ''];
        $post['files[' . $i++ . ']'] = new CURLFile($fpath, $mime, $fname);
    }
    $ch = curl_init(BASE . $path);
    curl_setopt_array($ch, [CURLOPT_POST => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_COOKIEFILE => $jar, CURLOPT_COOKIEJAR => $jar, CURLOPT_TIMEOUT => 60,
        CURLOPT_HTTPHEADER => ['Accept: application/json'], CURLOPT_POSTFIELDS => $post]);
    $body = (string) curl_exec($ch);
    $code = (int) curl_getinfo($ch, CURLINFO_HTTP_CODE);
    return [$code, json_decode($body, true) ?? ['raw' => $body]];
}

/** One worker pass as cron would run it, with extra environment: its printed line. */
function worker(array $env = []): string
{
    $pre = '';
    foreach ($env as $k => $v) { $pre .= escapeshellarg($k . '=' . $v) . ' '; }
    return trim((string) shell_exec('cd ' . escapeshellarg(dirname(__DIR__, 3)) . ' && env ' . $pre . 'php bin/worker.php 2>&1'));
}

/** SQL as postgres on the scratch database (what the application's role may not do: move a clock past a trigger). */
function su_sql(string $sql): string
{
    return trim((string) shell_exec('sudo -n -u postgres psql -v ON_ERROR_STOP=1 -qtA -d ' . escapeshellarg(need('DB_NAME')) . ' -c ' . escapeshellarg($sql) . ' 2>&1'));
}

function source_of(int $id): array { return q('SELECT * FROM sources WHERE id = :id', ['id' => $id])[0] ?? []; }
function sections_of(int $source): array { return q('SELECT * FROM sections WHERE source_id = :s ORDER BY position', ['s' => $source]); }
function source_id_titled(int $base, string $title): ?int { $v = one('SELECT id FROM sources WHERE base_id = :b AND (title = :t OR origin = :t) ORDER BY id DESC LIMIT 1', ['b' => $base, 't' => $title]); return $v === false || $v === null ? null : (int) $v; }
/** The planted phrase in any activity row? */
function plant_in_log(): bool { return (int) one("SELECT count(*) FROM activity_log WHERE coalesce(before::text, '') || coalesce(after::text, '') || coalesce(route, '') LIKE :p", ['p' => '%' . PLANT . '%']) > 0; }

